ANNOTATIONS = [
    (19, 'after_block', r'''【文件定位】消息列表的 React 层虚拟化。ScrollBox 早已在 Ink 输出层做了视口裁剪（render-node-to-output.ts:617 会跳过可见窗口外的子节点），但 React fiber 和 Yoga 节点仍然全部分配——按每条 MessageRow 约 250KB RSS 算，1000 条消息的会话就是约 250MB 只增不减的内存（Ink 屏幕缓冲、WASM 线性内存、JSC 页保留都是 grow-only）。这个 hook 只挂载视口 ± overscan 内的条目，其余用 spacer 盒子以每条 O(1) 的 fiber 成本撑住滚动高度。'''),
    (19, 'after', r'''未测条目的估算高度故意取低：高估会提前停止挂载导致视口底部露出空白 spacer，低估只是多挂几条进 overscan。不对称代价，宁可偏低。'''),
    (24, 'after', r'''视口上下各多渲染 80 行。给得慷慨是因为真实高度可能是估算值的 10 倍（长工具结果）。'''),
    (26, 'after', r'''ScrollBox 完成布局前（viewportHeight=0）先渲染的条目数。'''),
    (37, 'after', r'''scrollTop 量化档位。没有它，滚轮每格（3-5 个 tick）都会触发一次完整的 React commit + Yoga calculateLayout() + Ink diff——CPU 尖峰。视觉滚动依然平滑：ScrollBox.forceRender 每次 scrollBy 都触发，Ink 从 DOM 节点读真实 scrollTop，与 React 怎么想无关。React 只在挂载范围必须移动时才需要重渲染；OVERSCAN_ROWS 的一半是最紧的安全档（保证换挡前至少还剩 40 行 overscan）。'''),
    (45, 'after', r'''计算覆盖率时未测条目的最坏高度假设。MessageRow 最小可以只有 1 行（单行工具调用）。用 1 保证挂载跨度物理上够到视口底部，不管条目实际多小——代价是条目大时多挂，overscan 吸收得了。'''),
    (47, 'after', r'''挂载条目数上限，给退化情况下的 fiber 分配兜底。'''),
    (57, 'after', r'''单次 commit 最多新挂载多少条。带着 PESSIMISTIC_HEIGHT=1 滚进新范围一次会挂 194 条（OVERSCAN_ROWS×2+viewportH）；每条新 MessageRow 渲染约 1.5ms（marked lexer + formatToken + ~11 次 createInstance）= ~290ms 同步阻塞。把范围分多次 commit 滑过去，每次的挂载成本有界；渲染期的 clamp（scrollClampMin/Max）把视口按在已挂载内容边缘，追赶期间不出空白。'''),
    (118, 'after_block', r'''【返回结构】range 是 [startIndex, endIndex) 半开区间；topSpacer/bottomSpacer 是上下 spacer 盒子的行高；measureRef 给每条挂载条目的根 Box 挂上，Yoga 布局后把算出的高度写进缓存；spacerRef 挂 topSpacer 盒子——它的 Yoga computedTop 就是 listOrigin；offsets[i] = 第 i 条上方的行数累计、offsets[n] = 总高（列表局部坐标，不含 ScrollBox 里更靠前的 logo 等兄弟节点）；getItemTop 读 Yoga computedTop（-1 = 未挂载或未布局）；getItemElement/getItemHeight 供 ScrollBox.scrollToElement 和 StickyTracker 用；scrollToIndex 设 scrollTop = offsets[i] + listOrigin，把条目弄进挂载区（精确屏幕位置靠后续 getItemTop）。'''),
    (120, 'after', r'''【高度策略】未测条目先用固定估算值，首次布局后换成真实 Yoga 高度。没有 scroll anchoring——overscan 吸收估算误差。stickyScroll 有个坑：render-node-to-output.ts:450 在 Ink 渲染期把 scrollTop 设为 maxScroll，这不触发 ScrollBox.subscribe，所以 at-bottom 检查在这里兜底：贴着底时不看 scrollTop 说什么，直接渲染最后 N 条。'''),
    (162, 'after', r'''函数签名。三个参数：scrollRef（ScrollBox 句柄）、itemKeys（条目 key 列表，identity 变化触发缓存 GC）、columns（终端列数）。'''),
    (197, 'after', r'''列宽变化时缓存高度整体按 oldCols/newCols 缩放而不是清空。清空会让悲观覆盖回溯一次性挂 ~190 条（每条未缓存 → PESSIMISTIC_HEIGHT=1 → 回溯 190 条才够 viewport+2×overscan），每条新挂载跑 marked.lexer + 语法高亮约 3ms，长会话首次 resize 就是 ~600ms 的 React reconcile。缩放让 heightCache 保持有值，回溯用近似真实高度，挂载范围保持紧凑；缩放值会被下一帧 useLayoutEffect 的真实 Yoga 高度覆盖。缩放还能避开「拉宽黑屏」bug：放大的旧 offsets 会超过新 scrollTop 让结束循环提前收尾，ratio<1 把高度往下缩，与新 Yoga 对齐。'''),
    (202, 'after', r'''冻结挂载范围两个渲染周期。已挂载条目有热 useMemo（marked.lexer、高亮）；按缩放/悲观估算重算范围会造成挂载/卸载churn（每条约 3ms = ~150ms 二次闪烁）。冻结两帧：第 1 帧 skipMeasurement（Yoga 还是旧宽度的），第 2 帧 useLayoutEffect 把新 Yoga 读进 heightCache，第 3 帧高度准确恢复常规重算。'''),
    (216, 'after', r'''listOrigin：列表在 content-wrapper 坐标系里的原点。scrollTop 是 content-wrapper 相对的，但 offsets[] 是列表局部的（0 = 第一个虚拟化条目）。ScrollBox 里排在本列表前面的兄弟节点（Messages.tsx 的 Logo、StatusNotices、截断分割线）会把条目 Yoga 位置整体抬高；不减掉这个原点，非 sticky 分支的 effLo/effHi 会虚高，start 越过实际在视口内的条目（sticky 刚断、scrollTop 接近 max 时点击/滚动出现空白视口）。从 topSpacer 的 Yoga computedTop 读——它是虚拟化区的第一个子节点，其 top 就是 listOrigin。不减去任何 item 采样，所以条目高度随渲染变化时（tmux resize：列宽变 → 重排 → 高度缩 → 旧的 item 采样相减会变负 → effLo 虚高 → 黑屏）无漂移。和 heightCache 一样有一帧滞后。'''),
    (244, 'after', r'''useSyncExternalStore 把重渲染绑到命令式滚动上。快照是 scrollTop 按 SCROLL_QUANTUM 分档的 bin——小幅滚动（多数滚轮 tick）Object.is 看到没变，React 整个跳过 commit + Yoga + Ink 周期，直到累计差值跨档。sticky 折进快照符号位，sticky→broken 也要触发：scrollToBottom 只置 sticky=true 不动 scrollTop（Ink 稍后移），其后的第一次 scrollBy 可能落在同一档里。NaN 哨兵 = ref 还没挂。注意快照用「目标位置」（scrollTop+pendingDelta）而不是已提交 scrollTop：scrollBy 只改 pendingDelta（渲染器跨帧排空），已提交值滞后；用目标值意味着 scrollBy 的 notify() 真的改变快照 → React 在 Ink 排空帧需要子节点之前就为目的地重挂。'''),
    (266, 'after', r'''isSticky = ScrollBox 贴着底。这是唯一稳定的「在底部」信号：scrollTop/scrollHeight 反映的都是上一次渲染的布局，而布局取决于我们渲染了什么（topSpacer+条目）——形成 range→layout→atBottom→range 反馈环。stickyScroll 由用户动作（scrollToBottom/scrollBy）、初始属性、以及 render-node-to-output 位置跟随（scrollTop≥prevMax → 钉到新 max → 置位）写入。渲染器的写入是反馈安全的：只翻转 false→true，只在已经在位置底部时，且此处为真只意味着「尾部走查、清 clamp」——与直接读 scrollTop==maxScroll 行为一致，减去不稳定。默认 true：ref 挂上前假定贴底（首次 Ink 渲染 sticky 会钉过去）。'''),
    (285, 'after', r'''GC 陈旧缓存条目（compaction、/clear、screenToggleId bump）。只在 itemKeys identity 变化时跑——滚动不碰 keys。itemRefs 靠卸载时 ref(null) 自清洁。'''),
    (294, 'after', r'''offsets 跨渲染缓存，靠 offsetVersion ref bump 失效。旧方案每渲染分配新 Array(n+1) 且跑 n 次 Map.get：27k 条会话按按键重复滚动速率（~11 commit/s）就是 ~30 万次查询/s 打在 freshly-allocated 数组上 → GC churn + ~2ms/渲染。版本号由 heightCache 写入方（measureRef、resize 缩放、GC）递增；不 setState——重建是渲染期读侧惰性（同一次 commit，零额外调度）；过去逼出内联计算的闪烁正是 setState 失效引起的。'''),
    (311, 'after', r'''totalHeight = offsets[n]，本列表全部条目的高度总和。'''),
    (328, 'after', r'''冷启动：ScrollBox 还没布局。渲染尾部——sticky 滚动会在首次 Ink 渲染时钉到底，这些正是用户实际看到的条目。之后任何上翻都走 scrollBy → subscribe 触发 → 带真实值重渲染。'''),
    (339, 'after', r'''sticky 兜底：render-node-to-output 可能已经移动了 scrollTop 而没通知我们，所以信「在底部」而不是陈旧快照。从尾部往回走，直到覆盖 viewport+overscan。'''),
    (378, 'after', r'''span 封顶。输入快于渲染时 pendingDelta 无限增长 → effLo..effHi 覆盖几百行未挂载内容 → 一次 commit 挂 194 条新 MessageRow → 3 秒以上同步阻塞 → 更多输入排队 → 下次 delta 更大。死亡螺旋。封顶把每次 commit 的新挂载数约束住；clamp（setClampBounds）在追赶期间把视口按在已挂载边缘，不出空白——滚动分几帧到达目标，而不是一次冻住几秒。'''),
    (411, 'after', r'''start 用二分查找。offsets 单调递增；旧的 while(start++) 线性扫描在 27k 条会话里每渲染迭代 ~27k 次（从底部滚，start≈27200）。O(log n)。'''),
    (428, 'after', r'''守卫：不要越过「已挂载但未测」的条目。挂载与 useLayoutEffect 测量之间有一个渲染窗口，此时卸载它们会让 topSpacer 用 DEFAULT_ESTIMATE，与真实跨度不符 → 闪烁。已挂载条目在 [prevStart, prevEnd) 里，只扫这一段，不扫全部 n。'''),
    (441, 'after', r'''覆盖率循环：按累计最佳已知高度（未测按 PESSIMISTIC_HEIGHT=1）扩展 end。不变量是 topSpacer + 真实高度之和 ≥ scrollTop + viewportH + overscan；这个过挂策略保证快速滚过未测区域时视口绝不露出空 spacer，下一渲染高度进缓存后范围自动收紧。'''),
    (455, 'after', r'''滑档上限：限制本次 commit 的新挂载量。滚进新范围本来会按 PESSIMISTIC_HEIGHT=1 覆盖率一次挂 194 条——~290ms React 渲染阻塞。按滚动速度触发（|上次 commit 以来 scrollTop 差| > 2×viewportH——按键重复 PageUp 每按约动 viewportH/2，3 次连按成批 = 快模式）。scrollBy（pendingDelta）和 scrollTo（直接写）都覆盖。普通单次 PageUp 或 sticky 断裂跳转不走这条。只封顶范围增长；收缩不设限。'''),
    (488, 'after', r'''freeze 计数在范围算完后递减。freeze 期间不更新 prevRangeRef，这样两帧冻结都用最初的 resize 前范围（不是消息中途变化时被 clamp 到 n 的版本）。'''),
    (504, 'after', r'''useDeferredValue 让 React 先用旧范围渲染（便宜——全 memo 命中）再过渡到新范围（贵——新挂载要跑 marked.lexer + formatToken）。紧急渲染保持 Ink 按输入速率绘制，新挂载发生在不阻塞的后台渲染里。这是 React 原生的时间分片：62ms 的新挂载阻塞变成可中断的。clamp 已经处理视口钉住，所以延迟范围短暂落后 scrollTop 没有视觉伪影。只延迟范围增长（start 前移/end 后移才有新挂载）；收缩便宜（卸载只是移除 fiber，不解析），延迟收缩会让过期 overscan 多留一跳——无害，但会挂测试对测量后收紧范围的精确断言。'''),
    (518, 'after', r'''跳变太大时 effStart 可能超过 effEnd（start 前跳而 dEnd 还停在旧范围的 end）。此时跳过延迟避免区间反转。sticky 也跳过：scrollToBottom 需要尾部现在就在——延迟的 dEnd 还在旧范围，渲染出不完整尾部，maxScroll 停在旧内容高度，「跳到底」短一截。sticky 吸附是单帧动作，不是连续滚动，时间分片用不上。'''),
    (528, 'after', r'''向下滚（pendingDelta>0）时绕过 effEnd 延迟让尾部立刻挂载。否则 clamp（基于 effEnd）把 scrollTop 压在离真底部差一口气的位置——用户往下滚，撞 clampMax，停住，React 追上 effEnd，clampMax 放宽，但用户已经松手了。卡在底部之前的感觉。effStart 保持延迟，所以上滚仍有时间分片（老消息解析才是贵的方向）。'''),
    (552, 'after', r'''最终 O(viewport) 兜底。中间的各层封顶（maxEnd、slide cap、deferred 取交集）约束 [start,end]，但 deferred+bypass 的组合能让 [effStart,effEnd] 溜出去：持续 PageUp 时并发模式跨 commit 交错 dStart 更新与 effEnd=end 旁路，有效窗口会比单独用立即值或延迟值都宽。10K 行恢复会话上表现为 PageUp 连打期间 +270MB RSS（Yoga Node 构造 + createWorkInProgress fiber 分配与滚动距离成正比）。按视口位置修剪远端，让 fiber 数无论 deferred 怎么调度都是 O(viewport)。修剪方向按视口位置定而不是 pendingDelta 方向：pendingDelta 帧间会排空到 0，而 dStart/dEnd 在并发调度下滞后，方向修剪会在稳定过程中从「修剪尾」翻成「修剪头」，顶高 effStart → effTopSpacer → clampMin → setClampBounds 把 scrollTop 猛往下拽 → 回滚消失。'''),
    (590, 'after', r'''clampMax 在 effEnd=n 时取 Infinity——没有 bottomSpacer 可防 racing past。这里不能用 offsets[n]：那会把 heightCache 烙进去（落后 Yoga 一个渲染），尾部条目正在流式输出时缓存高度落后于真实高度，sticky 断裂后把 scrollTop 压在低于真 max 的位置，把流式文本推出视口（「往上翻，回复不见了」bug）。Infinity = 不设限，交给 render-node-to-output 自己的 Math.min(cur, maxScroll) 管。'''),
    (612, 'after', r'''测量上一个 Ink 渲染的高度。每个 commit 都跑（无 deps）——Yoga 重算布局时 React 不知道。区分「h=0：Yoga 还没跑」（瞬态，跳过）与「h=0：MessageRow 渲染了 null」（永久，缓存）：getComputedWidth()>0 证明 Yoga 已经布局过这个节点（宽度来自容器，列里的 Box 永远非零）。宽度有值而高度为 0，条目就是真空——缓存 0，免得 start 前移闸门被它永远卡住（否则一条 null 消息卡在起始边界会冻住范围，表现为上翻后往下滚出现空白视口）。不 setState——那会调度第二次 commit，而 Ink 每次 commit 都写 stdout，两次不同 spacer 高度的写入就是可见闪烁。高度下一个自然渲染进 offsets，一帧滞后，overscan 吸收。'''),
    (645, 'after', r'''ref(null) 路径在卸载时抓高度：yogaNode 那时还有效（reconciler 先调 ref(null) 再 removeChild → freeRecursive），所以能在 WASM 释放前拿到最终测量值。'''),
    (705, 'after', r'''scrollToIndex 读 offsetsRef.current 而不是渲染期闭包的 offsets——事件处理器跑在两次渲染之间，闭包值会陈旧。'''),
    (707, 'after', r'''bottomSpacer = 总高 - offsets[effEnd]，即最后一条挂载条目之后的高度。'''),
]
